SELECT TA040 as MOCTATA040,CMSMD.MD002 as CMSMDMD002,MOCTA.TA001 as MOCTATA001,MOCTA.TA002 as MOCTATA002,MOCTA.TA006 AS MOCTATA006,MOCTA.TA034 as MOCTATA034 ,MOCTA.TA035 as MOCTATA035,MOCTA.TA015 as MOCTATA015,MOCTB.TB003 as MOCTBTB003,MOCTB.TB012 as MOCTBTB012,MOCTB.TB013 as MOCTBTB013,MOCTB.TB007 as MOCTBTB007,INVMB.MB090 as MB090,MOCTB.TB004 as MOCTBTB004,MOCTB.TB005 as MOCTBTB005,MOCTB.TB004-MOCTB.TB005 as MOCTB001, ( SELECT SUM(ISNULL(INVMC.MC007,0)) FROM  $$INVMB as INVMB  left join $$INVMC as INVMC on INVMB.MB001=INVMC.MC001 left JOIN $$CMSMC AS CMSMC ON INVMC.MC002 = CMSMC.MC001 where CMSMC.MC005='Y' and INVMC.MC007>0  and  MB001=TB003 ) AS WHS006, (select sum(TH007) from   $$PURTH where  TH030 = 'N' and TH004=TB003) TH007,(select sum(TB007) from $$INVTB AS INVTB where TB004=TB003 AND TB018 = 'N' and TB001='1112') TB007,MOCTA.UDF02 AS MOCTAUDF02 FROM $$MOCTB as MOCTB  join $$INVMB as INVMB on TB003=MB001  Left JOIN $$MOCTA as MOCTA On MOCTB.TB001=MOCTA.TA001 and MOCTB.TB002=MOCTA.TA002  Left JOIN $$CMSMD as CMSMD On MOCTA.TA021=CMSMD.MD001  WHERE &&OpenOption AND ((MOCTA.TA011 = '2') OR (MOCTA.TA011 = '3') or (MOCTA.TA011 = case :TA011A when 'N' then '2' else '1' end ))  ORDER BY CMSMD.MD002 asc,MOCTA.TA001 asc,MOCTA.TA002 asc
